SELECT city AS cityName, SUM(CASE WHEN financial_type = 1 THEN balance ELSE 0 END) AS incomeTotal, SUM(CASE WHEN financial_type = 2 THEN balance ELSE 0 END) AS expenseTotal, SUM(balance) AS totalAmount FROM dc_financial_statistics
AND financial_type = #{financialType}
AND city = #{city}
AND source_type = #{sourceType}
AND DATE(flow_time) >= DATE(#{startTime})
AND DATE(flow_time) <= DATE(#{endTime})
AND creater_name LIKE CONCAT('%', #{createrName}, '%')
GROUP BY city ORDER BY totalAmount DESC

SELECT source_type AS sourceType, SUM(balance) AS total, COUNT(*) AS count FROM dc_financial_statistics
AND financial_type = #{financialType}
AND city = #{city}
AND source_type = #{sourceType}
AND DATE(flow_time) >= DATE(#{startTime})
AND DATE(flow_time) <= DATE(#{endTime})
AND creater_name LIKE CONCAT('%', #{createrName}, '%')
GROUP BY source_type ORDER BY total DESC

SELECT financial_type AS financialType, SUM(balance) AS total, COUNT(*) AS count FROM dc_financial_statistics
AND financial_type = #{financialType}
AND city = #{city}
AND source_type = #{sourceType}
AND DATE(flow_time) >= DATE(#{startTime})
AND DATE(flow_time) <= DATE(#{endTime})
AND creater_name LIKE CONCAT('%', #{createrName}, '%')
GROUP BY financial_type ORDER BY total DESC
